const w=t=>new Set(String(t||"").toLowerCase().match(/[a-z0-9^]{2,}/g)||[]);function h(t){const o=new Set,i=[];for(const a of t.answers||[]){const c=w(a.text);let s=null,e=0;for(const n of t.questions||[]){if(o.has(n.id))continue;const f=w(n.text);let r=0;for(const u of c)f.has(u)&&r++;const d=r/Math.max(1,Math.min(c.size,f.size));d>e&&(e=d,s=n)}s&&e>=.1&&(o.add(s.id),i.push({questionId:s.id,answerId:a.id,confidence:Math.min(.9,.4+e)}))}return{pairs:i}}export{h as default};
